export const EXPECTED_TOTAL_FRAMES = 4500;
export const TOTAL_FRAMES = SCENES.reduce((sum, s) => sum + s.durationInFrames, 0);

if (TOTAL_FRAMES !== EXPECTED_TOTAL_FRAMES) {
  throw new Error(/* ... */);
}

export const CHUNKS: readonly ChunkSpec[] = Array.from(
  { length: Math.ceil(TOTAL_FRAMES / CHUNK_FRAMES) },
  (_, i) => ({
    index: i + 1,
    id: `SealcoinChunk${String(i + 1).padStart(2, "0")}`,
    fromFrame: i * CHUNK_FRAMES,
    durationInFrames: Math.min(CHUNK_FRAMES, TOTAL_FRAMES - i * CHUNK_FRAMES),
  }),
);
